// Mapa "ID do grupo do WhatsApp" -> "id do hangar" (usado em config/hangares.json).
// Ao cadastrar um novo hangar: adicionar uma linha aqui E uma entrada em config/hangares.json.
const GRUPO_PARA_HANGAR = {
  // 'SEU_ID_DO_GRUPO_SOLOJET@g.us': 'solojet',
  // 'SEU_ID_DO_GRUPO_AIBM@g.us': 'aibm',
};

const body = $input.item.json.body || $input.item.json;
const grupoId = body.grupoId;
const hangarId = GRUPO_PARA_HANGAR[grupoId] || body.hangarId; // fallback p/ testes manuais

if (!hangarId) {
  throw new Error(`Grupo "${grupoId}" não está cadastrado em GRUPO_PARA_HANGAR nem foi enviado hangarId diretamente.`);
}

return {
  json: {
    ...body,
    hangarId,
  },
};

// Os scripts imprimem UM json por linha em stdout (console.log). Pega a última linha não-vazia.
const stdout = $input.item.json.stdout || '';
const linhas = stdout.trim().split('\n').filter(Boolean);
const ultimaLinha = linhas[linhas.length - 1];

let resultado;
if (!ultimaLinha) {
  resultado = {
    status: 'erro',
    mensagem: 'O script não retornou nenhuma saída (stdout vazio).',
    mensagemWhatsapp: '⚠️ Erro interno ao processar o ticket. Nossa equipe foi avisada.',
    notificarAdmin: true,
  };
} else {
  try {
    resultado = JSON.parse(ultimaLinha);
  } catch (erro) {
    resultado = {
      status: 'erro',
      mensagem: `Não consegui interpretar a saída do script: ${ultimaLinha}`,
      mensagemWhatsapp: '⚠️ Erro interno ao processar o ticket. Nossa equipe foi avisada.',
      notificarAdmin: true,
    };
  }
}

if (!resultado.mensagemWhatsapp) {
  resultado.mensagemWhatsapp = '⚠️ Não conseguimos processar essa solicitação. Nossa equipe foi avisada.';
  resultado.notificarAdmin = true;
}

return { json: resultado };
